script:
(function(){
  var ENDPOINT = "https://evolve-crm-ivory.vercel.app/api/coa-lookup";
  var SAMPLE = { stats:{batches:41,products:65,avgPurity:98.6,labs:["MZ Biolabs","Janoshik","Chromate"]}, batches:[
    {lotNumber:"3468012957",compound:"Retatrutide",strength:"5mg",purityPct:99.97,analysisDate:"2025-12-29",method:"HPLC-UV-MS",labName:"MZ Biolabs",endotoxinPass:true,coaImageUrl:"#",endotoxinImageUrl:"#",products:[{id:1,name:"Retatrutide 5 mg",url:"#",status:"publish"}]},
    {lotNumber:"3168572049",compound:"Tirzepatide",strength:"5mg",purityPct:99.76,analysisDate:"2025-12-29",method:"HPLC-UV-MS",labName:"MZ Biolabs",endotoxinPass:true,coaImageUrl:"#",endotoxinImageUrl:"#",products:[{id:2,name:"Tirzepatide 5 mg",url:"#",status:"publish"}]},
    {lotNumber:"1395827460",compound:"Semax",strength:"5mg",purityPct:99.91,analysisDate:"2025-12-29",method:"HPLC-UV-MS",labName:"MZ Biolabs",endotoxinPass:true,coaImageUrl:"#",endotoxinImageUrl:"#",products:[{id:3,name:"Semax 5 mg",url:"#",status:"publish"}]}
  ]};
  var $ = function(id){return document.getElementById(id);};
  var input=$("evoInput"), btn=$("evoBtn"), result=$("evoResult"), statsEl=$("evoStats"), examplesEl=$("evoExamples");
  var DATA=null, byLot={};
  function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
  function fmtDate(iso){ if(!iso) return "n/a"; try{var d=new Date(iso+"T00:00:00Z");return d.toLocaleDateString("en-US",{year:"numeric",month:"short",day:"numeric",timeZone:"UTC"});}catch(e){return iso;} }
  function loading(){ result.innerHTML='<div class="msg"><div class="spinner"></div></div>'; }
  function index(){ byLot={}; (DATA.batches||[]).forEach(function(b){ if(b.lotNumber) byLot[String(b.lotNumber).replace(/\s+/g,"")]=b; }); }
  function renderStats(){
    var s=DATA.stats||{};
    var labs=(s.labs&&s.labs.length)?s.labs:[];
    var items=[["Purity analysis","HPLC"],["Safety screening","Endotoxin"],[labs.length?labs.join(" · "):"Third-party tested", labs.length?(labs.length+" independent lab"+(labs.length>1?"s":"")):"Independent"]];
    statsEl.innerHTML=items.map(function(i){return '<div class="stat"><b>'+esc(i[1])+'</b><span>'+esc(i[0])+'</span></div>';}).join("");
  }
  function renderExamples(){
    var all=(DATA.batches||[]).filter(function(b){return b.lotNumber;});
    var good=all.filter(function(b){return b.purityPct!=null&&b.endotoxinPass===true&&b.strength;}).sort(function(a,b){return b.purityPct-a.purityPct;});
    var picks=(good.length>=3?good:all).slice(0,3);
    picks.forEach(function(b){ var el=document.createElement("button"); el.type="button"; el.textContent=b.lotNumber; el.addEventListener("click",function(){ input.value=b.lotNumber; go(); }); examplesEl.appendChild(el); });
  }
  function doc(href,title,sub){ if(!href||href==="#"||href==null) return ""; return '<button type="button" class="doc" data-doc="'+esc(href)+'" data-title="'+esc(title)+'"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg><span>'+esc(title)+'<small>'+esc(sub)+'</small></span></button>'; }
  var modalBack=null;
  function initModal(){
    if(modalBack) return;
    modalBack=document.createElement("div"); modalBack.className="evo-docmodal";
    modalBack.innerHTML='<div class="box" role="dialog" aria-modal="true" aria-label="Lab report"><div class="head"><b class="t"></b><div class="r"><a class="op" href="#" target="_blank" rel="noopener">Open in new tab</a><button type="button" class="x" aria-label="Close">×</button></div></div><div class="body"></div></div>';
    document.body.appendChild(modalBack);
    modalBack.addEventListener("click",function(e){ if(e.target===modalBack) closeDoc(); });
    modalBack.querySelector(".x").addEventListener("click",closeDoc);
    document.addEventListener("keydown",function(e){ if(e.key==="Escape") closeDoc(); });
  }
  function openDoc(href,title){
    initModal();
    var isPdf=/\.pdf($|\?)/i.test(href);
    modalBack.querySelector(".t").textContent=title||"Lab report";
    modalBack.querySelector(".op").setAttribute("href",href);
    modalBack.querySelector(".body").innerHTML = isPdf
      ? '<object data="'+esc(href)+'" type="application/pdf"><div class="pdffb">This report opens as a PDF. <a href="'+esc(href)+'" target="_blank" rel="noopener">Tap here to view it.</a></div></object>'
      : '<img decoding="async" src="'+esc(href)+'" alt="'+esc(title||"Lab report")+'" loading="lazy">';
    modalBack.classList.add("open"); document.body.style.overflow="hidden";
  }
  function closeDoc(){ if(!modalBack) return; modalBack.classList.remove("open"); modalBack.querySelector(".body").innerHTML=""; document.body.style.overflow=""; }
  function renderBatch(b){
    var endo = b.endotoxinPass===true?'<span class="badge pass">Pass</span>':b.endotoxinPass===false?'<span class="badge fail">Fail</span>':'<span class="badge na">Not on file</span>';
    var purity = b.purityPct!=null? b.purityPct.toFixed(2).replace(/\.00$/,"")+"%":"n/a";
    var products=(b.products||[]).filter(function(p){return p.status==="publish"&&p.url&&p.url!=="#";});
    var foundHtml = products.length? '<div class="found">Found in: '+products.map(function(p){return '<a href="'+esc(p.url)+'">'+esc(p.name)+'</a>';}).join(", ")+'</div>' : (b.products&&b.products.length? '<div class="found">Product: '+esc(b.products[0].name)+'</div>':"");
    result.innerHTML =
      '<div class="card">'+
        '<div class="card-top"><div><h2 class="compound">'+esc(b.compound||"Peptide")+(b.strength?' <span class="strength">'+esc(b.strength)+'</span>':'')+'</h2><div class="lotline">Batch #'+esc(b.lotNumber)+'</div></div></div>'+
        (b.purityPct!=null? '<div class="purity"><div class="num">'+esc(purity)+'</div><div class="meta"><b>Purity</b>'+esc(b.method||"HPLC")+'</div></div>':'')+
        '<div class="grid">'+
          '<div class="cell"><p class="k">Endotoxin</p><div class="v">'+endo+'</div></div>'+
          '<div class="cell"><p class="k">Analysis date</p><div class="v">'+esc(fmtDate(b.analysisDate))+'</div></div>'+
          '<div class="cell"><p class="k">Testing lab</p><div class="v">'+esc(b.labName||"Independent lab")+'</div></div>'+
          '<div class="cell"><p class="k">Method</p><div class="v">'+esc(b.method||"HPLC")+'</div></div>'+
        '</div>'+
        ((b.coaImageUrl&&b.coaImageUrl!=="#")||(b.endotoxinImageUrl&&b.endotoxinImageUrl!=="#")? '<div class="docs">'+doc(b.coaImageUrl,"Certificate of Analysis","Full purity report")+doc(b.endotoxinImageUrl,"Endotoxin Report","LAL assay")+'</div>':'')+
        foundHtml+
      '</div>';
  }
  function renderNone(q){ result.innerHTML='<div class="msg err"><h3>No report found for batch '+esc(q)+'</h3><p>Double-check the number printed on your label. If it looks right, contact us and we\'ll pull the report for you.</p></div>'; }
  function go(){
    var q=(input.value||"").trim().replace(/\s+/g,"");
    if(!q){ result.innerHTML=""; return; }
    try{ history.replaceState(null,"", location.pathname+"?batch="+encodeURIComponent(q)); }catch(e){}
    var b=byLot[q];
    if(b) renderBatch(b); else renderNone(q);
  }
  function start(){
    renderStats(); renderExamples(); index(); initModal();
    btn.addEventListener("click",go);
    input.addEventListener("keydown",function(e){ if(e.key==="Enter") go(); });
    result.addEventListener("click",function(e){ var b=e.target.closest&&e.target.closest("[data-doc]"); if(b) openDoc(b.getAttribute("data-doc"), b.getAttribute("data-title")); });
    var m=(location.search||"").match(/[?&](?:batch|lot)=([^&]+)/i);
    if(m){ input.value=decodeURIComponent(m[1]); go(); }
  }
  loading();
  var done=false, timer=setTimeout(function(){ if(!done){ done=true; DATA=SAMPLE; result.innerHTML=""; start(); } },4000);
  fetch(ENDPOINT,{headers:{Accept:"application/json"}}).then(function(r){return r.json();}).then(function(j){
    if(done) return; done=true; clearTimeout(timer);
    DATA=(j&&Array.isArray(j.batches)&&j.batches.length)?j:SAMPLE;
    result.innerHTML=""; start();
  }).catch(function(){ if(done) return; done=true; clearTimeout(timer); DATA=SAMPLE; result.innerHTML=""; start(); });
})();

styles:
#evolve-age-gate{position:fixed;inset:0;z-index:2147483000;display:none;align-items:center;justify-content:center;padding:28px;font-family:"Outfit","Segoe UI",system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;background:rgba(26,11,38,.5);-webkit-backdrop-filter:blur(7px) saturate(.9);backdrop-filter:blur(7px) saturate(.9);}
html.evolve-age-show{overflow:hidden;}
html.evolve-age-show #evolve-age-gate{display:flex;}
#evolve-age-gate .eag-card{width:100%;max-width:468px;background:#fff;border-radius:20px;padding:44px 44px 34px;text-align:center;box-shadow:0 40px 90px -30px rgba(10,4,18,.75);}
#evolve-age-gate img.eag-logo{max-width:210px;height:auto;margin:0 auto 24px;display:block;}
#evolve-age-gate .eag-eyebrow{font-size:11.5px;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:#715588;margin:0 0 14px;}
#evolve-age-gate h2.eag-q{font-size:29px;line-height:1.12;letter-spacing:-.02em;font-weight:700;margin:0 0 10px;color:#241033;}
#evolve-age-gate .eag-sub{font-size:15px;color:#6f6779;margin:0 auto 26px;max-width:34ch;line-height:1.5;}
#evolve-age-gate .eag-actions{display:flex;flex-direction:column;gap:11px;}
#evolve-age-gate .eag-btn{font-family:inherit;font-size:16px;font-weight:600;cursor:pointer;border-radius:12px;padding:15px 18px;border:1.5px solid transparent;width:100%;transition:background .15s ease,transform .1s ease;}
#evolve-age-gate .eag-btn:active{transform:translateY(1px);}
#evolve-age-gate .eag-yes{background:#230F33;color:#fff;box-shadow:0 12px 26px -12px rgba(35,15,51,.85);}
#evolve-age-gate .eag-yes:hover{background:#301546;}
#evolve-age-gate .eag-no{background:#f4f1f7;color:#715588;}
#evolve-age-gate .eag-no:hover{background:#ebe5f1;}
#evolve-age-gate .eag-btn:focus-visible{outline:3px solid #8f74a6;outline-offset:2px;}
#evolve-age-gate .eag-rule{height:1px;background:#ece7f1;margin:26px 0 18px;border:0;}
#evolve-age-gate .eag-legal{font-size:11.5px;line-height:1.6;color:#6f6779;margin:0 auto;max-width:40ch;}
#evolve-age-gate .eag-legal b{color:#4b3a5c;font-weight:600;}
@media (max-width:520px){#evolve-age-gate .eag-card{padding:34px 24px 28px;}#evolve-age-gate h2.eag-q{font-size:25px;}#evolve-age-gate img.eag-logo{max-width:180px;}}
@media (prefers-reduced-motion:no-preference){#evolve-age-gate .eag-card{animation:eagRise .5s cubic-bezier(.2,.7,.2,1) both;}@keyframes eagRise{from{opacity:0;transform:translateY(14px) scale(.985);}to{opacity:1;transform:none;}}}

:root{
    --aubergine:#230F33; --aubergine-deep:#1a0b26; --mauve:#715588; --mauve-soft:#8f74a6;
    --ink:#241033; --muted:#6f6779; --hair:#ece7f1; --hair-strong:#ddd4e6;
    --bg:#ffffff; --card:#ffffff; --chip:#f4f1f7;
    --pass:#1f7a4d; --pass-bg:#e7f4ec; --fail:#b23b3b; --fail-bg:#fbecec;
    --sans:"Outfit","Segoe UI",system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;
    --r:16px;
  }
  *{box-sizing:border-box}
  .evo-coa{font-family:var(--sans);color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;line-height:1.5;padding:clamp(20px,5vw,64px) 20px 72px}
  .evo-coa .wrap{max-width:720px;margin:0 auto}
  .evo-coa .eyebrow{font-size:12px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--mauve);margin:0 0 12px}
  .evo-coa h1{font-size:clamp(28px,5vw,42px);line-height:1.08;letter-spacing:-.02em;font-weight:700;margin:0 0 12px;text-wrap:balance}
  .evo-coa .lede{font-size:clamp(15px,2.2vw,18px);color:var(--muted);max-width:46ch;margin:0 0 28px}
  .evo-coa .stats{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 32px}
  .evo-coa .stat{flex:1 1 140px;background:var(--card);border:1px solid var(--hair);border-radius:12px;padding:14px 16px}
  .evo-coa .stat b{display:block;font-size:22px;font-weight:700;letter-spacing:-.01em;font-variant-numeric:tabular-nums;color:var(--aubergine)}
  .evo-coa .stat span{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
  .evo-coa .search{background:linear-gradient(160deg,#2a1240,var(--aubergine) 60%,var(--aubergine-deep));border-radius:var(--r);padding:clamp(20px,4vw,32px);color:#fff;box-shadow:0 24px 60px -34px rgba(26,4,26,.7)}
  .evo-coa .search label{display:block;font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#cdbcde;margin:0 0 10px}
  .evo-coa .field{display:flex;gap:10px}
  .evo-coa .field input{flex:1;min-width:0;font-family:inherit;font-size:18px;font-variant-numeric:tabular-nums;letter-spacing:.02em;padding:15px 16px;border-radius:11px;border:1.5px solid transparent;background:#fff;color:var(--ink);outline:none}
  .evo-coa .field input:focus-visible{border-color:var(--mauve-soft);box-shadow:0 0 0 4px rgba(143,116,166,.35)}
  .evo-coa .field button{font-family:inherit;font-size:16px;font-weight:600;color:#fff;background:var(--mauve);border:0;border-radius:11px;padding:0 22px;cursor:pointer;transition:background .15s,transform .1s;white-space:nowrap}
  .evo-coa .field button:hover{background:#836399}
  .evo-coa .field button:active{transform:translateY(1px)}
  .evo-coa .examples{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:14px;font-size:13px;color:#cdbcde}
  .evo-coa .examples button{font-family:inherit;font-variant-numeric:tabular-nums;font-size:13px;color:#efe8f5;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);border-radius:999px;padding:5px 12px;cursor:pointer;transition:background .15s}
  .evo-coa .examples button:hover{background:rgba(255,255,255,.2)}
  .evo-coa .result{margin-top:22px;min-height:2px}
  .evo-coa .card{background:var(--card);border:1px solid var(--hair);border-radius:var(--r);overflow:hidden;box-shadow:0 20px 50px -38px rgba(26,4,26,.5);animation:rise .35s cubic-bezier(.2,.7,.2,1) both}
  @media (prefers-reduced-motion:reduce){.evo-coa .card{animation:none}}
  @keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
  .evo-coa .card-top{display:flex;flex-wrap:wrap;align-items:flex-start;justify-content:space-between;gap:12px;padding:22px 24px;border-bottom:1px solid var(--hair)}
  .evo-coa .compound{font-size:24px;font-weight:700;letter-spacing:-.01em;margin:0}
  .evo-coa .compound .strength{color:var(--mauve);font-weight:600}
  .evo-coa .lotline{font-size:13px;color:var(--muted);margin-top:4px;font-variant-numeric:tabular-nums}
  .evo-coa .status{font-size:12px;font-weight:600;padding:5px 11px;border-radius:999px;background:var(--chip);color:var(--mauve);white-space:nowrap}
  .evo-coa .purity{display:flex;align-items:baseline;gap:14px;padding:22px 24px;background:linear-gradient(180deg,#fbfafc,#fff)}
  .evo-coa .purity .num{font-size:clamp(40px,10vw,58px);font-weight:700;letter-spacing:-.03em;line-height:1;color:var(--aubergine);font-variant-numeric:tabular-nums}
  .evo-coa .purity .meta{font-size:13px;color:var(--muted)}
  .evo-coa .purity .meta b{display:block;font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--mauve)}
  .evo-coa .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;background:var(--hair)}
  .evo-coa .cell{background:#fff;padding:16px 24px}
  .evo-coa .cell .k{font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin:0 0 4px}
  .evo-coa .cell .v{font-size:15px;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums}
  .evo-coa .badge{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;padding:3px 10px;border-radius:999px}
  .evo-coa .badge.pass{background:var(--pass-bg);color:var(--pass)}
  .evo-coa .badge.fail{background:var(--fail-bg);color:var(--fail)}
  .evo-coa .badge.na{background:var(--chip);color:var(--muted)}
  .evo-coa .docs{display:flex;flex-wrap:wrap;gap:10px;padding:20px 24px;border-top:1px solid var(--hair)}
  .evo-coa .doc{flex:1 1 200px;display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--aubergine);font-family:inherit;font-weight:600;font-size:14px;text-align:left;cursor:pointer;background:#fff;border:1.5px solid var(--hair-strong);border-radius:12px;padding:13px 16px;transition:border-color .15s,background .15s}
  .evo-coa .doc:hover{border-color:var(--mauve-soft);background:#fbfafc}
  .evo-coa .doc svg{flex:none;color:var(--mauve)}
  .evo-coa .doc small{display:block;font-weight:500;font-size:12px;color:var(--muted)}
  .evo-coa .found{padding:16px 24px;border-top:1px solid var(--hair);font-size:13px;color:var(--muted)}
  .evo-coa .found a{color:var(--aubergine);font-weight:600;text-decoration:none}
  .evo-coa .found a:hover{text-decoration:underline}
  .evo-coa .msg{background:var(--card);border:1px solid var(--hair);border-radius:var(--r);padding:26px 24px;text-align:center}
  .evo-coa .msg h3{margin:0 0 6px;font-size:18px}
  .evo-coa .msg p{margin:0;color:var(--muted);font-size:14px}
  .evo-coa .msg.err{border-color:#e7c9c9;background:#fdf6f6}
  .evo-coa .spinner{width:22px;height:22px;border:2.5px solid var(--hair-strong);border-top-color:var(--mauve);border-radius:50%;margin:0 auto;animation:spin .7s linear infinite}
  @keyframes spin{to{transform:rotate(360deg)}}
  .evo-coa .foot{margin-top:26px;font-size:12px;color:var(--muted);text-align:center}
  @media(max-width:520px){.evo-coa .grid{grid-template-columns:1fr}}
  .evo-docmodal{position:fixed;inset:0;z-index:2147483000;display:none;align-items:center;justify-content:center;padding:16px;background:rgba(26,4,26,.72);font-family:var(--sans)}
  .evo-docmodal.open{display:flex}
  .evo-docmodal .box{background:#fff;border-radius:16px;width:100%;max-width:900px;max-height:94vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 40px 90px -25px rgba(0,0,0,.55)}
  .evo-docmodal .head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 18px;border-bottom:1px solid var(--hair);flex:none}
  .evo-docmodal .head b{font-size:15px;font-weight:700;color:var(--aubergine)}
  .evo-docmodal .head .r{display:flex;align-items:center;gap:6px}
  .evo-docmodal .head a{font-size:13px;font-weight:600;color:var(--mauve);text-decoration:none;padding:6px 10px;border-radius:8px}
  .evo-docmodal .head a:hover{background:var(--chip)}
  .evo-docmodal .head button{background:none;border:0;font-size:24px;line-height:1;color:var(--muted);cursor:pointer;padding:2px 10px;border-radius:8px}
  .evo-docmodal .head button:hover{background:var(--chip);color:var(--ink)}
  .evo-docmodal .body{flex:1;min-height:0;overflow:auto;background:var(--chip);display:flex;align-items:flex-start;justify-content:center}
  .evo-docmodal .body img{max-width:100%;height:auto;display:block}
  .evo-docmodal .body object,.evo-docmodal .body iframe{width:100%;height:82vh;border:0}
  .evo-docmodal .pdffb{padding:44px 24px;text-align:center;color:var(--muted);font-size:15px}
  .evo-docmodal .pdffb a{color:var(--aubergine);font-weight:700}
